	"expira_em" timestamp with time zone NOT NULL,
	"resposta" varchar(12),
	"respondida_em" timestamp with time zone,
	CONSTRAINT "pk_aviso_cadastro" PRIMARY KEY("id"),
	CONSTRAINT "uq_aviso_cadastro_token" UNIQUE("token_hash"),
	CONSTRAINT "ck_aviso_cadastro_resposta" CHECK (resposta IS NULL OR resposta IN ('SOU_EU','NAO_FUI_EU')),
